// String - creates new object each time
string result = "";
for (int i = 0; i < 1000; i++) {
    result += i.ToString(); // New object each iteration!
}

// StringBuilder - efficient
var sb = new StringBuilder();
for (int i = 0; i < 1000; i++) {
    sb.Append(i); // Same buffer
}
string result = sb.ToString();
